import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 amount, uint256 lockTime) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        uint afterContractBalance = address(c).balance;
        assertTrue(reverted || (afterBalance >= beforeBalance && afterContractBalance == beforeContractBalance + amount));
    }

    function testFuzz_run(uint256 amount, uint256 lockTime) public {
        _run(amount, lockTime);
    }

    receive() external payable {}
}
